        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 71,
        marker = "#",
        depth = 1,
        instruction = "Second password (if you wish to skip this, head directly to the 3rd map via exit A (Castle Oztroja Map 1 J-8)and follow directions for the third password): Now head to the door at Castle Oztroja Map 1 I-8 and then go up the stairs to the 2nd map. On this map, head to the exit at Castle Oztroja Map 3... Required details: J-8, I-8, G-7, I-7, H-9, Map Map 2, Map Map 7, Map Map 3, Map Map 1, Map 1, Map 3, Map 7, Map 2.",
        action = "travel",
        entities = {  },
        zones = { "Castle Oztroja" },
        map_numbers = { "Map 2", "Map 7", "Map 3", "Map 1", "1", "3", "7", "2" },
        grid_coordinates = { "J-8", "I-8", "G-7", "I-7", "H-9" },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 72,
        marker = "#",
        depth = 1,
        instruction = "Third password: Proceed back along the same path to the 3rd map. The 3rd statue is located on the NW corner of Castle Oztroja Map 3 I-8. If you've never experienced this section of the map before there are blocker points preventing most of the \"obvious\" paths and forcing you to walk around the outside.",
