        entities = {  },
        zones = { "Castle Oztroja" },
        map_numbers = { "Map 3", "3" },
        grid_coordinates = { "I-8" },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 73,
        marker = "#",
        depth = 1,
        instruction = "From the 3rd statue point head to the 4 lever door at the SW corner of Castle Oztroja Map 3 G-8. You can find the current combination of the levers at the dead-end at (Castle Oztroja Map 3 I-10). If you were not aggroed before you will be once going through this door, plan accordingly!",
