        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 74,
        marker = "#",
        depth = 1,
        instruction = "Once through the door, head up the stairs and zone over (Castle Oztroja Map 3 G-9) onto a new map.",
        action = "note",
        entities = {  },
        zones = { "Castle Oztroja" },
        map_numbers = { "Map 3", "3" },
