        key_items = {  },
        warnings = {  },
      },
      {
        order = 75,
        marker = "#*",
        depth = 2,
        instruction = "This part is pretty straightforward: just remain invisible, don't step on the Yagudo Parasites (leeches), and proceed to the next map at Castle Oztroja Map 4 H-11.",
        action = "note",
        entities = {  },
        zones = { "Castle Oztroja" },
        map_numbers = { "Map 4", "4" },
        grid_coordinates = { "H-11" },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 76,
        marker = "#",
        depth = 1,
        instruction = "You want to proceed through the Brass door at Castle Oztroja Map 5 H-7 from here. In order to open it, someone must light one of the 4 torches at Castle Oztroja Map 5 G-7, Castle Oztroja Map 5 G-8, Castle Oztroja Map 5 H-7, or Castle Oztroja Map 5 H-8. If you brought help that has NOT done Magicite (Mission 4) you can light the torch while they pass... Required details: Hide, H-7, G-7, G-8, H-8, Map Map 5, Map 5.",
