        entities = { "Hide" },
        zones = { "Castle Oztroja" },
        map_numbers = { "Map 5", "5" },
        grid_coordinates = { "H-7", "G-7", "G-8", "H-8" },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 77,
        marker = "#",
        depth = 1,
        instruction = "Once through the brass door, there will be a wooden plank with a red circle (trap door) in front of a Brass Statue. Have everyone stand on the plank. Click on the statue and input the passwords in the order shown on the Vana'diel Atlas maps. The trap door will open and everyone will fall through to the bottom. Don't worry about invisibility, as the bottom of the trap door is safe.",
