        entities = { "Brass Statue" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 78,
        marker = "#",
        depth = 1,
        instruction = "Once everyone has dropped down through the trap door, recast invisibility, and run down the long corridor leading to a large room with a series of ramps up to a center platform and a higher rear platform. The ??? to get the Yagudo crest is located on the lower central platform. At this point you'll need to keep a lookout for the Yagudo NM High Priest.",
