        entities = { "???", "Yagudo crest" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 79,
        marker = "#*",
        depth = 2,
        instruction = "Invisible will work on all the Yagudo in this area except the Notorious Monsters. Tzee Xicu the Manifest, Yagudo Avatar, Yagudo High Priest & Yagudo Templar all have True Sight, so make sure you're well away from their sight line as they will attack when they see you.",
