        marker = "#*",
        depth = 2,
        instruction = "Wait for the Yagudo NM to be sufficiently far away from the center platform, then travel up the ramps to the center platform, standing behind any regular Yagudo which may be on that platform, drop invis, click the ??? and re-invis.",
