    steps = {
      {
        order = 1,
        marker = "*",
        depth = 1,
        instruction = "Talk to Nomad Moogle near Maat in Ru'Lude Gardens, Select the option to accept the challenge to receive the key item Soul gem clasp(You MUST trade a Seasoning Stone to the Nomad Moogle to get the Key Item.)The Nomad Moogle then offers to Teleport you to Horlais Peak, Waughroon Shrine, Balga's Dais or Qu'Bia Arena for the fight you can also select \"Nowhere yet\" to do the fight later.",
