      },
      {
        order = 6,
        marker = "*",
        depth = 1,
        instruction = "Note: Blessed Radiance - After you have completed this quest your NPC will sometimes use Blessed Radiance when one or both of your HP gauges are in the red.",
        action = "note",
        entities = { "Blessed Radiance (Ability)" },
        zones = {  },
